    syncWindowStateFromPayload(payload) {
      if (!payload) return;
      if (typeof payload === 'string') {
        this.isMaximized = payload === 'maximized';
        this.isExpanded = this.isMaximized;
        return;
      }
      const state = payload.state || '';
      this.isMaximized = Boolean(payload.isMaximized || state === 'maximized');
      this.isExpanded = this.isMaximized;
    },
