    syncAccessDialogScrollLock(forceClear = false) {
      if (typeof document === 'undefined') {
        return;
      }
      const applyState = () => {
        const shouldLock = !forceClear && (
          this.showLoginDialog ||
          this.showAccessLegalDialog ||
          this.showPersonalCenterDialog ||
          this.showUnlockDialog ||
          this.showFakeQrDialog
        );
        const targets = [
          document.documentElement,
          document.body,
          document.getElementById('app'),
        ].filter(Boolean);
        targets.forEach((target) => {
          target.classList.toggle('openxnet-auth-dialog-scroll-lock', shouldLock);
        });
      };
      if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
        window.requestAnimationFrame(applyState);
        return;
      }
      applyState();
    },
