    getPrototypeModelProviderCards() {
      const configuredProviders = this.getPrototypeConfiguredProviders();
      if (configuredProviders.length > 0) {
        return configuredProviders;
      }
      return this.getPrototypeProviderTemplates();
    },
    getPrototypeProviderLogo(provider) {
      return this.getVendorLogo(provider?.logoVendor || provider?.setupVendor || provider?.vendor);
    },
    getPrototypeProviderDisplayName(provider) {
      return String(provider?.displayVendor || provider?.vendor || '').trim() || this.t('provider');
    },
    getPrototypeProviderStatusLabel(provider) {
      if (provider?.isTemplate) {
        return provider.statusLabel;
      }
      const hasUrl = !!String(provider?.url || '').trim();
      const hasModel = !!String(provider?.modelId || '').trim();
      if (hasUrl && hasModel) {
        return this.isCurrentLanguageZh() ? '已连接' : 'Connected';
      }
      if (hasUrl) {
        return this.isCurrentLanguageZh() ? '待选择模型' : 'Model pending';
      }
      return this.isCurrentLanguageZh() ? '未配置' : 'Not configured';
    },
    getPrototypeProviderStatusTone(provider) {
      if (provider?.isTemplate) {
        return provider.statusTone || 'muted';
      }
      const hasUrl = !!String(provider?.url || '').trim();
      const hasModel = !!String(provider?.modelId || '').trim();
      if (hasUrl && hasModel) {
        return 'success';
      }
      return hasUrl ? 'warning' : 'muted';
    },
    getPrototypeProviderSummaryText(provider) {
      if (provider?.isTemplate) {
        return provider.summaryText;
      }
      const modelsCount = Array.isArray(provider?.models)
        ? provider.models.map((item) => this.getProviderModelOptionValue(item)).filter(Boolean).length
        : 0;
      if (modelsCount > 0) {
        return this.isCurrentLanguageZh()
          ? `${modelsCount} 个模型已配置`
          : `${modelsCount} models configured`;
      }
      return this.isCurrentLanguageZh() ? '未设置' : 'Unset';
    },
    isPrototypeModelProviderActive(provider) {
      if (provider?.isTemplate) {
        return provider.id === this.prototypeModelProviderSelection;
      }
      return this.isProviderSelectedAsMain(provider?.id);
    },
    copyProviderById(providerId) {
      const providerIndex = this.modelProviders.findIndex((item) => String(item?.id ?? '').trim() === String(providerId ?? '').trim());
      if (providerIndex < 0) return;
      this.copyProvider(this.modelProviders[providerIndex], providerIndex);
    },
    async removeProviderById(providerId) {
      const providerIndex = this.modelProviders.findIndex((item) => String(item?.id ?? '').trim() === String(providerId ?? '').trim());
      if (providerIndex < 0) return;
      await this.removeProvider(providerIndex);
    },
