    /** 刷新 VRM 展示在线状态；Desktop 查询 Main 窗口，Browser/Server 查询兼容 route。 */
    async refreshVRMRuntimeState() {
      try {
        if (this.isElectron) {
          if (typeof window.openxnetDesktop?.getApplicationVrmPresentationStatus !== 'function') {
            throw new Error('Desktop VRM presentation bridge is unavailable.');
          }
          const status = await window.openxnetDesktop.getApplicationVrmPresentationStatus();
          this.vrmOnline = Number(status?.connections || 0) > 0;
          return;
        }
        const response = await fetch('/tts/status');
        if (!response.ok) {
          throw new Error('Failed to fetch VRM status');
        }
        const payload = await response.json();
        this.vrmOnline = (payload?.vrm_connections || 0) > 0;
      } catch (error) {
        this.vrmOnline = false;
      }
    },
    async refreshPrototypeDeployStatus(itemId = this.subMenu) {
      const targetId = String(itemId || this.subMenu || '').trim();
      if (targetId === 'im_bot') {
        const tasks = [
          this.checkQQBotStatus,
          this.checkFeishuBotStatus,
          this.checkDingtalkBotStatus,
          this.checkTelegramBotStatus,
          this.checkDiscordBotStatus,
          this.checkSlackBotStatus,
        ].filter((fn) => typeof fn === 'function')
          .map((fn) => fn.call(this));
        await Promise.allSettled(tasks);
        return;
      }
      if (targetId === 'live_stream') {
        if (typeof this.checkLiveStatus === 'function') {
          await this.checkLiveStatus();
        }
        return;
      }
      if (targetId === 'table_pet') {
        await this.refreshVRMRuntimeState();
        return;
      }
      await this.autoSaveSettings();
    },
