    async refreshPrototypeApiStatus(itemId = this.subMenu) {
      const targetId = String(itemId || this.subMenu || '').trim();
      if (targetId === 'develop') {
        await this.loadDevWorkbench();
        return;
      }
      if (targetId === 'extension') {
        if (typeof this.fetchRemotePlugins === 'function') {
          await this.fetchRemotePlugins();
          return;
        }
        if (typeof this.scanExtensions === 'function') {
          await this.scanExtensions();
          return;
        }
      }
      if (targetId === 'vrm') {
        await this.refreshVRMRuntimeState();
        return;
      }
      await this.autoSaveSettings();
    },
