      if (target === 'shortcuts') {
        this.refreshGlobalShortcutStatus?.();
      }
      if (target === 'about' && this.isElectron && window.electronAPI?.getAppVersion) {
        window.electronAPI.getAppVersion()
          .then((version) => {
            if (version) this.updateCurrentVersion = String(version);
          })
          .catch((error) => console.warn('Load app version failed:', error));
      }
