    /** 通过 Desktop typed IPC 或 Browser HTTP 执行直播生命周期；输入操作，返回兼容结果并先保存待提交凭据。 */
    async requestApplicationLiveRuntime(operation) {
      const desktopMethods = {
        status: 'getApplicationLiveRuntimeStatus',
        start: 'startApplicationLiveRuntime',
        stop: 'stopApplicationLiveRuntime',
        reload: 'reloadApplicationLiveRuntime',
      };
      if (isElectron) {
        const method = window.openxnetDesktop?.[desktopMethods[operation]];
        if (typeof method !== 'function') {
          throw new Error('Live Runtime Desktop IPC is unavailable.');
        }
        if (operation === 'start' || operation === 'reload') {
          if (!(this._pendingLivePlatformCredentialFields instanceof Set)) {
            this._pendingLivePlatformCredentialFields = new Set();
          }
          this.getApplicationLivePlatformCredentialFields().forEach((field) => {
            if (String(this.liveConfig?.[field] || '').trim()) {
              this._pendingLivePlatformCredentialFields.add(field);
            }
          });
          await this.autoSaveSettings();
          const result = await method({
            configuration: this.buildApplicationLiveRuntimeConfiguration(),
          });
          return {
            success: result?.success === true,
            is_running: result?.isRunning === true,
            details: result?.details || {},
            message: result?.success === true
              ? ''
              : result?.errorCode === 'LIVE_RUNTIME_UNAVAILABLE'
                ? '直播运行时不可用，请先安装对应功能包。'
                : '直播运行时操作失败，请检查配置。',
          };
        }
        const result = await method();
        return {
          success: result?.success === true,
          is_running: result?.isRunning === true,
          details: result?.details || {},
          message: result?.success === true ? '' : '直播运行时操作失败。',
        };
      }

      const routes = {
        status: '/api/live/status',
        start: '/api/live/start',
        stop: '/api/live/stop',
        reload: '/api/live/reload',
      };
      const options = operation === 'status'
        ? undefined
        : {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            ...(
              operation === 'start' || operation === 'reload'
                ? { body: JSON.stringify({ config: this.buildLegacyLivePlatformSettingsPayload() }) }
                : {}
            ),
          };
      const response = await fetch(routes[operation], options);
      return response.json();
    },

