    /** 返回 SQL 凭据字段白名单；无输入，返回固定字段数组，无副作用。 */
    getApplicationSqlCredentialFields() {
      return ['password'];
    },

    /** 判断 Desktop SQL 安全桥是否可用；无输入，返回布尔值，无副作用。 */
    isDesktopSqlRuntimeAvailable() {
      return typeof window.openxnetDesktop?.startApplicationMcpRuntime === 'function'
        && typeof window.openxnetDesktop?.selectApplicationSqliteDatabase === 'function';
    },

    /** 规范旧 SQL 设置；输入未知设置，返回含统一 dbpath 和脱敏口令的新对象。 */
    normalizeLegacySqlSettingsPayload(value) {
      const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
      const config = { ...this.sqlSettings, ...source };
      config.dbpath = String(config.dbpath || source.dbPath || '').trim();
      delete config.dbPath;
      config.databaseId = String(config.databaseId || '').trim();
      config.sqlCredentialFieldsConfigured = Array.isArray(config.sqlCredentialFieldsConfigured)
        ? [...config.sqlCredentialFieldsConfigured]
        : [];
      if (typeof window.openxnetDesktop?.saveApplicationSqlCredentials === 'function') {
        config.password = '';
      }
      return config;
    },

    /** 构建一次 SQL 口令修改；无输入，返回精确写入请求，不包含未完成编辑。 */
    buildApplicationSqlCredentialSaveRequest() {
      const credentials = {};
      const pending = this._pendingSqlCredentialFields instanceof Set
        ? this._pendingSqlCredentialFields
        : new Set();
      if (pending.has('password')) {
        const secret = String(this.sqlSettings?.password || '').trim();
        if (secret) credentials.password = secret;
      }
      return { credentials, clear: [] };
    },

    /** 构建兼容 SQL 设置；无输入，返回分离副本，Desktop 模式不包含口令。 */
    buildLegacySqlSettingsPayload() {
      const config = this.normalizeLegacySqlSettingsPayload(this.sqlSettings);
      if (typeof window.openxnetDesktop?.saveApplicationSqlCredentials === 'function') {
        config.password = '';
      }
      return config;
    },

    /** 标记 SQL 口令完成编辑；输入字段名，返回保存 Promise 或空值，未知字段不产生副作用。 */
    markApplicationSqlCredentialForSave(field) {
      if (typeof window.openxnetDesktop?.saveApplicationSqlCredentials !== 'function') {
        return this.autoSaveSettings();
      }
      if (!this.getApplicationSqlCredentialFields().includes(field)) return undefined;
      if (!(this._pendingSqlCredentialFields instanceof Set)) {
        this._pendingSqlCredentialFields = new Set();
      }
      this._pendingSqlCredentialFields.add(field);
      return this.autoSaveSettings();
    },

    /** 应用 Main 脱敏 SQL 快照；输入快照，无返回，清空 Renderer 口令并同步文件授权。 */
    applyApplicationSqlCredentialSnapshot(snapshot) {
      if (!Array.isArray(snapshot?.configured) || !this.sqlSettings) return;
      this.sqlSettings.password = '';
      this.sqlSettings.sqlCredentialFieldsConfigured = [...snapshot.configured];
      this.sqlSettings.databaseId = String(snapshot.database?.databaseId || '');
      this.sqlSettings.dbpath = String(snapshot.database?.displayPath || this.sqlSettings.dbpath || '');
    },

    /** 判断 SQL 口令是否刚输入或已安全保存；输入字段名，返回布尔值，无副作用。 */
    isApplicationSqlCredentialConfigured(field) {
      return Boolean(
        String(this.sqlSettings?.[field] || '').trim()
        || this.sqlSettings?.sqlCredentialFieldsConfigured?.includes(field),
      );
    },

    /** 返回 SQL 口令占位文案；输入字段和后备文本，返回脱敏提示，不读取密钥。 */
    getApplicationSqlCredentialPlaceholder(field, fallback = '') {
      if (!this.isApplicationSqlCredentialConfigured(field)) return fallback;
      return this.isCurrentLanguageZh()
        ? '已安全保存，输入新值可替换'
        : 'Stored securely; enter a new value to replace';
    },

    /** 显式清除 Main SQL 口令；输入字段名，无返回，成功后停止 SQL 并保存脱敏设置。 */
    async clearApplicationSqlCredential(field) {
      if (typeof window.openxnetDesktop?.saveApplicationSqlCredentials !== 'function') return;
      const snapshot = await window.openxnetDesktop.saveApplicationSqlCredentials({ clear: [field] });
      this.applyApplicationSqlCredentialSnapshot(snapshot);
      this.sqlSettings.enabled = false;
      await this.autoSaveSettings();
    },

