  async saveNewTTSConfig() {
    const name = String(this._editingTTSName || this.newTTSConfig.name || '').trim();
    if (!name || name === 'default') return;
    this.newTTSConfig.name = name;

    this.ttsSettings.newtts[name] = { ...this.newTTSConfig };
    if (typeof window.openxnetDesktop?.saveApplicationVoiceCredentials === 'function') {
      const draftFields = this._pendingVoiceDraftCredentialFields instanceof Set
        ? this._pendingVoiceDraftCredentialFields
        : new Set();
      this.getApplicationVoiceCredentialFields().forEach((field) => {
        if (draftFields.has(field) || String(this.newTTSConfig[field] || '').trim()) {
          if (!(this._pendingVoiceCredentialEntries instanceof Set)) {
            this._pendingVoiceCredentialEntries = new Set();
          }
          this._pendingVoiceCredentialEntries.add(JSON.stringify([name, field]));
        }
      });
    }
    this.showAddTTSDialog = false;
    await this.autoSaveSettings();
    this.getApplicationVoiceCredentialFields().forEach((field) => {
      this.newTTSConfig[field] = '';
    });
    this._pendingVoiceDraftCredentialFields?.clear();
    this._editingTTSName = null;
  },

  async deleteTTS(name) {
    delete this.ttsSettings.newtts[name];
    if (typeof window.openxnetDesktop?.saveApplicationVoiceCredentials === 'function') {
      await this.clearApplicationVoiceCredentials(name);
      return;
    }
    await this.autoSaveSettings();
  },

