  getKernelConsoleActionKey(action = {}) {
    return action.queueKey || `${action.plan_id || 'plan'}:${action.actionType || 'inspect'}:${action.step_id || 'plan'}`;
  },

  isKernelConsoleActionExpanded(action = {}) {
    const key = this.getKernelConsoleActionKey(action);
    return Boolean((this.kernelConsoleExpandedActions || {})[key]);
  },

  toggleKernelConsoleActionDetail(action = {}) {
    const key = this.getKernelConsoleActionKey(action);
    if (!key) return;
    const expanded = { ...(this.kernelConsoleExpandedActions || {}) };
    if (expanded[key]) {
      delete expanded[key];
    } else {
      expanded[key] = true;
    }
    this.kernelConsoleExpandedActions = expanded;
  },

  getKernelConsoleActionSearchText(action = {}) {
    const plan = action.plan || {};
    const candidates = [
      action.plan_id,
      action.actionType,
      action.queueStatus,
      action.reason,
      action.message,
      action.step_id,
      plan.goal_preview,
      plan.status,
      action.lastRunStatus,
      action.lastRunStopReason,
    ];
    return candidates.map((item) => String(item || '').toLowerCase()).join(' ');
  },

  getKernelConsoleVisibleActions() {
    const query = String(this.kernelConsoleActionSearch || '').trim().toLowerCase();
    const visible = this.getKernelConsoleActions().filter((action) => {
      if (this.kernelConsoleActionFilter !== 'all' && action.actionType !== this.kernelConsoleActionFilter) {
        return false;
      }
      if (this.kernelConsoleResumeFilter === 'resumable' && !action.canResume) {
        return false;
      }
      if (this.kernelConsoleResumeFilter === 'blocked' && !action.isBlocked) {
        return false;
      }
      if (this.kernelConsoleResumeFilter === 'human' && !action.requiresHuman) {
        return false;
      }
      if (this.kernelConsoleResumeFilter === 'approval' && !action.requiresApproval) {
        return false;
      }
      if (this.kernelConsoleResumeFilter === 'complete' && !action.isComplete) {
        return false;
      }
      if (query && !this.getKernelConsoleActionSearchText(action).includes(query)) {
        return false;
      }
      return true;
    });
    return visible.slice().sort((left, right) => {
      const sortMode = this.kernelConsoleActionSort || 'priority';
      if (sortMode === 'age') {
        return Number(right.ageSeconds || 0) - Number(left.ageSeconds || 0);
      }
      if (sortMode === 'updated') {
        return Date.parse(right.updatedAt || 0) - Date.parse(left.updatedAt || 0);
      }
      if (sortMode === 'plan') {
        const leftName = String(left.plan?.goal_preview || left.plan_id || '');
        const rightName = String(right.plan?.goal_preview || right.plan_id || '');
        return leftName.localeCompare(rightName);
      }
      return Number(left.priority || 80) - Number(right.priority || 80);
    });
  },

  getKernelConsoleSelectedRuns() {
    const explicitRuns = this.kernelConsoleSelectedPlanRuns;
    if (explicitRuns && Array.isArray(explicitRuns.runs)) return explicitRuns.runs.slice(-5).reverse();
    const control = this.kernelConsoleSelectedPlanControl || {};
    const recent = control.runs?.recent;
    return Array.isArray(recent) ? recent.slice().reverse() : [];
  },

