  handleKernelPrototypeExport() {
    const payload = {
      runtime: this.kernelConsoleRuntime || {},
      status: this.kernelConsoleStatus || {},
      board: this.kernelConsoleControlBoard || {},
      queue: this.kernelConsoleActionQueue || {},
      audit: this.kernelPrototypeAuditRowsData || [],
      traces: this.kernelPrototypeTraceCardsData || [],
      plans: this.kernelPrototypeRecentPlans || [],
      world: this.kernelPrototypeWorldSnapshot || {},
      selectedPlan: {
        id: this.kernelConsoleSelectedPlanId || '',
        control: this.kernelConsoleSelectedPlanControl || null,
        timeline: this.kernelConsoleSelectedPlanTimeline || null,
        runs: this.kernelConsoleSelectedPlanRuns || null,
      },
      exportedAt: new Date().toISOString(),
    };
    try {
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `kernel-status-${Date.now()}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      showNotification(this.isCurrentLanguageZh() ? '内核状态已导出' : 'Kernel status exported', 'success');
    } catch (error) {
      showNotification(this.isCurrentLanguageZh() ? '导出失败：' + (error?.message || error) : 'Export failed: ' + (error?.message || error), 'error');
    }
  },

