  getKnowledgePrototypeSelectedKbDetailRows() {
    const kb = this.getKnowledgePrototypeSelectedKb();
    if (!kb) return [];
    return [
      { label: this.isCurrentLanguageZh() ? '状态' : 'Status', value: this.getKbPrototypeStatusLabel(kb) },
      { label: this.isCurrentLanguageZh() ? '文档数' : 'Documents', value: Array.isArray(kb.files) ? kb.files.length : 0 },
      { label: this.isCurrentLanguageZh() ? '嵌入模型' : 'Embedding', value: kb.model || this.getKnowledgePrototypeConfiguredEmbeddingLabel() },
      { label: this.isCurrentLanguageZh() ? '分块大小' : 'Chunk Size', value: kb.chunk_size || '-' },
      { label: this.isCurrentLanguageZh() ? '重叠大小' : 'Overlap', value: kb.chunk_overlap || '-' },
      { label: this.isCurrentLanguageZh() ? 'Top-K' : 'Top-K', value: kb.chunk_k || this.KBSettings?.top_n || '-' },
    ];
  },

  openKnowledgePrototypeDetail(kb) {
    if (!kb?.id) return;
    this.kbPrototypeSelectedKbId = kb.id;
    this.showKbPrototypeDetailDialog = true;
  },

  /**
   * 重建一个知识库；输入知识库对象，无返回，更新处理状态并在失败时记录固定错误。
   */
  async rebuildKnowledgeBase(kb) {
    if (!kb?.id || kb?.builtin) return;
    try {
      kb.processingStatus = 'processing';
      kb.processingError = '';
      await this.autoSaveSettings();
      if (this.isDesktopKnowledgeBaseRuntimeAvailable()) {
        void this.runDesktopKnowledgeBaseBuild(kb.id);
        if (typeof showNotification === 'function') {
          showNotification(this.isCurrentLanguageZh() ? '已开始重建知识库索引' : 'Knowledge base rebuild started', 'success');
        }
        return;
      }
      const response = await fetch('/create_kb', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ kbId: kb.id }),
      });
      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
      }
      this.loadKnowledgePrototypePage({ silent: true });
      if (typeof showNotification === 'function') {
        showNotification(this.isCurrentLanguageZh() ? '已开始重建知识库索引' : 'Knowledge base rebuild started', 'success');
      }
    } catch (error) {
      kb.processingStatus = 'failed';
      kb.processingError = error?.message || String(error);
      console.error('Rebuild knowledge base failed:', error);
      if (typeof showNotification === 'function') {
        showNotification((this.isCurrentLanguageZh() ? '重建知识库失败：' : 'Failed to rebuild KB: ') + (error?.message || error), 'error');
      }
    }
  },

